"""Urdu XII PDF107 (spread): pp.204–205 — Poem 4 'شکست کی آواز' (Meeraji, d.1949 — public domain) full text (source پابند نظمیں)."""
from class12_book_common import Book, Builder

BOOK = Book('urdu')
t = Builder()
t.h('The Sound of Defeat — Meeraji', 'شکست کی آواز — میراجیؔ', 'د ماتې غږ — میراجي')
C = [
 [('Longings have cast my heart into a strange tangle;', 'اُمنگوں نے مرے دل کو عجب اُلجھن میں ڈالا ہے', 'ارمانونو زما زړه په عجیبه ګډوډۍ کې اچولی؛'),
  ('it thinks that whatever task there is, it is the one to do it.', 'سمجھتا ہے کہ جو بھی کام ہے وہ کرنے والا ہے', 'ګڼي چې هر کار چې دی، همدا یې کوونکی دی.')],
 [('It says: let me show new paths to the riders;', 'یہ کہتا ہے نئے رستے دکھاؤں میں سواروں کو', 'وايي: سپرو ته نوې لارې وښیم؛'),
  ('it says: let me bring down the moon-pieces from the sky.', 'یہ کہتا ہے کہ لے آؤں فلک سے ماہ پاروں کو', 'وايي: له اسمانه د سپوږمۍ ټوټې راکوز کړم.')],
 [('It says: let me cross the distance of deserts in a moment —', 'یہ کہتا ہے کہ صحراؤں کی دوری طے کروں پل میں', 'وايي: د صحراوو واټن په یوه شېبه کې ووهم —'),
  ('in truth, it is this conscious feeling I would cross in a moment.', 'حقیقت میں، یہ احساسِ شعوری طے کروں پل میں', 'په حقیقت کې، دا شعوري احساس په یوه شېبه کې ووهم.')],
 [('Let me go and see the new world that lies in the heart of the sea;', 'جہانِ نَو کو دیکھ آؤں جو ہے قلبِ سمندر میں', 'هغه نوې نړۍ ولیدو ته لاړ شم چې د سمندر په زړه کې ده؛'),
  ('the tale of the stone-forest lies frozen on the mountain’s head.', 'بیانِ سنگ پالوں منجمد ہے کوہ کے سر میں', 'د ډبرینو ځنګلونو کیسه د غره پر سر کنګل شوې ده.')],
 [('It says: let the whole universe become a single speck;', 'یہ کہتا ہے کہ ساری کائنات اک ذرہ بن جائے', 'وايي: ټوله کائنات دې یوه ذره شي؛'),
  ('let the interval that is infinite become just one moment.', 'جو ہے لا انتہا وقفہ وہ بس اک لمحہ بن جائے', 'کوم وقفه چې بې‌پایه ده، دې یوازې یوه شېبه شي.')],
 [('But what of it if intentions are lofty? Lofty intentions', 'مگر اُونچے ارادے ہیں تو کیا، اُونچے ارادوں کو', 'خو که اراده لوړه ده نو څه؟ لوړې ارادې'),
  ('simple folk have no sense to understand.', 'سمجھنے کا نہیں احساس حاصل سیدھے سادوں کو', 'ساده خلک یې د پوهېدو احساس نه لري.')],
 [('In the world simple people live in great numbers;', 'جہاں میں سیدھے سادے آدمی کثرت سے بستے ہیں', 'په نړۍ کې ساده خلک په ډېر شمېر اوسېږي؛'),
  ('limited is their courage and limited their paths.', 'ہے محدود اُن کی ہمت اور محدود اُن کے رستے ہیں', 'همت یې محدود دی او لارې یې محدودې دي.')],
 [('Civilisation and cultures have cast their noose upon them;', 'تمدن اور تہذیبوں نے پھندا اُن پہ ڈالا ہے', 'تمدن او تهذیبونو پرې خپله لومه اچولې ده؛'),
  ('they say: what is to be is only what is bound to be.', 'وہ کہتے ہیں کہ ہونا ہے وہی جو ہونے والا ہے', 'هغوی وايي: هماغه کېږي چې کېدونکی دی.')],
 [('“Changing them, what shall we do with the ways of Nature today?', 'بدل کر کیا کریں گے ہم طریقے آج قدرت کے', '"نن به موږ د قدرت لارې بدلې کړو نو څه به وکړو؟'),
  ('Tomorrow the hands of Fate will be upon our skirts.”', 'ہمارے دامنوں پر ہاتھ کل ہوں گے مشیت کے', 'سبا به زموږ پر لمنو د تقدیر لاسونه وي."')],
 [('They find comfort in the poverty of the lines drawn before;', 'اُنھیں تسکین ہے پہلی لکیروں کی فقیری میں', 'هغوی ته د پخوانیو کرښو په فقیرۍ کې ډاډ دی؛'),
  ('they are lost in the weakness and old age of desire.', 'یہ کھوئے ہیں تمنا کی ضعیفی اور پیری میں', 'دوی د ارمان په کمزورۍ او زوړتوب کې ورک دي.')],
 [('I look at them and they leave their mark on my heart;', 'میں اُن کو دیکھتا ہوں دل پہ ہوتا ہے اثر اُن کا', 'زه دوی ته ګورم او زما پر زړه یې اغېز کېږي؛'),
  ('I am one oppressed by the stagnant pull of this environment.', 'میں اک مظلوم ہوں ماحول کے اس جذبِ ساکن کا', 'زه د دې چاپېریال د ولاړې جذبې یو مظلوم یم.')],
 [('But yes — in spite of this, there is a blaze in my heart:', 'مگر ہاں باوجود اس کے مرے دل میں جُوالا ہے', 'خو هو — سره له دې، زما په زړه کې لمبه ده:'),
  ('longings have cast my being into a tangle.', 'اُمنگوں نے مری ہستی کو اک اُلجھن میں ڈالا ہے۔', 'ارمانونو زما هستي په یوه ګډوډۍ کې اچولې.')],
]
for c in C:
    t.group('lines', c)
t.p('(Paband Nazmen)', '(پابند نظمیں)', '(پابند نظمونه)')
po = BOOK.record(t, 'urdu12-u21-poem', 'Poem text', 'متنِ نظم', 'د نظم متن', 107, [204, 205])
issues = [{'id': 'urdu12-pdf107', 'unit': 21, 'printedPage': 204, 'description': 'p.204 line 8 prints “بیانِ سنگ پالوں منجمد ہے کوہ کے سر میں” — “سنگ پالوں” is obscure (possibly a misprint for “سنگ زاروں” / “سنگ پاروں”); retained as printed and translated by sense. Faint quill-and-inkpot background drawing is decorative.'}]

if __name__ == '__main__':
    BOOK.save(107, [(21, po)], issues=issues)
